package com.hrms.employee.entity;

import com.hrms.common.audit.Auditable;
import com.hrms.common.enums.Gender;
import com.hrms.common.util.BooleanToNumberConverter;
import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDate;

/**
 * Training record of an employee (table EMPLOYEE_TRAINING, created by V5). Never deleted, only deactivated.
 * Generated by tools/generate_employee_info.py.
 */
@Entity
@Table(name = "EMPLOYEE_TRAINING", schema = "HRMS")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class EmployeeTraining extends Auditable {

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "employee_training_seq")
    @SequenceGenerator(name = "employee_training_seq", sequenceName = "HRMS.SEQ_EMPLOYEE_TRAINING", allocationSize = 1)
    @Column(name = "TRAINING_ID", nullable = false)
    private Long id;

    @Column(name = "EMPLOYEE_ID", nullable = false)
    private Long employeeId;

    @Column(name = "COURSE_NAME", nullable = false, length = 200)
    private String courseName;

    @Column(name = "COURSE_NAME_AR", columnDefinition = "NVARCHAR2(200)")
    private String courseNameAr;

    @Column(name = "PROVIDER", length = 200)
    private String provider;

    @Column(name = "START_DATE")
    private LocalDate startDate;

    @Column(name = "END_DATE")
    private LocalDate endDate;

    @Convert(converter = BooleanToNumberConverter.class)
    @Column(name = "IS_ACTIVE", nullable = false)
    private Boolean isActive;

    /** Optimistic lock: a stale writer gets HTTP 409. */
    @Version
    @Column(name = "VERSION", nullable = false)
    private Long version;
}
